    for (int k = 0; k <= n; ++k) {
        long long ways = comb(n, k);
        ways = ways * fact[n] % MOD;
        ways = ways * inv_fact[k] % MOD;
        ways = ways * inv_fact[n - k] % MOD;
        long long term = ways * mod_pow(2, n - k, MOD) % MOD;
        term = term * mod_pow(2, k, MOD) % MOD;
        ans = (ans + term) % MOD;
