    f[0] = g[0] = 1;
    for (int i = 1; i <= n; i++) {
        f[i] = 1LL * f[i - 1] * i % MOD;
        g[i] = 1LL * g[i - 1] * inv[i] % MOD;
    }
    pw[0] = 1;
    for (int i = 1; i <= n; i++) pw[i] = 2LL * pw[i - 1] % MOD;
